  Section Post.
    Variables (m' : mem) (b1 actx : Z).
    Let idv := d_putid d (depot_hash T).
    Let P := outside W.
    Hypothesis MU : munch W m m'.
    Hypothesis WM : ltac2:(zQ "20!ij6!inb@3$1$0?1m?2m'").
    Hypothesis B1 : ltac2:(zQ "60!io4!la!ioa!hmf!iof!ip5@2$0@2$0@2$3Z?2b1@2$4?2b1+hg0@3$1$2@2$5?2b1+o0+h1").
    Hypothesis HDR' : rw_cells asegs m' (U + -16) [C1 (b8 3); C1 (b8 b1); C2 (wz 0); C4 (wz size); C8 (wz actx)].
    Hypothesis UW' : rw_cells asegs m' U [C8 (wz idv)].
    Hypothesis TST' : stk asegs m' (TH + 2800) (TH + 3168).
    Hypothesis UNW' : rw_cells asegs m' (TH + 3168) [C1 (b8 0)].
    Hypothesis FLG' : ltac2:(zQ "a0!itb!ivb!jg3!jk4!jka!ij6!jl1!jla!jpb!jq7@4$8$5?2m'$6@3$1$0@1$2@1$3+1@3$1$0@1$2@1$3Z@3$1$0@1$7@1$9Z@1$4$0").
    Hypothesis IA' : ltac2:(zQ "10!juc@1$0?2m'").
    Hypothesis SHF' : u8arr asegs m' (sh U) (repeat (b8 kAsanHeapFreeMagic) (Z.to_nat (nsh size))).

    Let AG : agree_on P m m'. Proof. apply munch_agree. exact MU. Qed.
    (* [comment removed for export] *)
    Let WQ' : WFQ (free_st' s ch tq' (as_cache st)) [ch_chunk_beg ch] [].
    Proof.
      change (free_st' s ch tq' (as_cache st)) with (flip_st st ch).
      exact (WFQ_flip_st st ch WFs CHIN ALLOC).
    Qed.

